// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type HighestPaidSkillsProps = Record<string, any>;

const HighestPaidSkills: React.FC<HighestPaidSkillsProps> = ({
  backgroundColor = "#FAFAFA",
  transparentBackground = false,
  durationInSeconds = 5,
  title = "Highest Paid Skills",
  titleColor = "#111827",
  primaryColor = "#F97316", // Vibrant Orange
  labelColor = "#374151",
  valueColor = "#FFFFFF",
  skills = [
    { name: "Sales", value: 320, customLabel: "Uncapped" },
    { name: "AI / Machine Learning", value: 280 },
    { name: "Cloud Architecture", value: 250 },
    { name: "Software Engineering", value: 210 },
    { name: "Product Management", value: 180 },
    { name: "Data Science", value: 160 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Sort skills descending to ensure the highest is at the top
  const sortedSkills = [...skills].sort((a, b) => b.value - a.value);

  // Layout calculations
  const maxSkillValue = Math.max(...sortedSkills.map((s) => s.value), 1);
  const maxBarWidth = width * 0.55; // Bars take up max 55% of screen width
  const labelWidth = width * 0.25; // Labels take up 25% of screen width
  
  // Title Animation
  const titleSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120 },
  });
  const titleY = interpolate(titleSpring, [0, 1], [-50, 0]);
  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        padding: "5%",
        transition: "none",
      }}
    >
      {/* Title */}
      <div
        style={{
          width: "100%",
          textAlign: "left",
          paddingLeft: "8%",
          marginBottom: "4%",
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
          transition: "none",
        }}
      >
        <h1
          style={{
            margin: 0,
            fontSize: width * 0.04,
            fontWeight: 800,
            color: titleColor,
            letterSpacing: "-0.02em",
            transition: "none",
          }}
        >
          {title}
        </h1>
      </div>

      {/* Chart Container */}
      <div
        style={{
          width: "90%",
          height: "70%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          borderLeft: `4px solid ${labelColor}20`, // Subtle axis line
          paddingTop: "1%",
          paddingBottom: "1%",
          transition: "none",
        }}
      >
        {sortedSkills.map((skill, index) => {
          // Staggered animation for each bar
          const delay = 15 + index * 6;
          const barSpring = spring({
            frame: Math.max(0, frame - delay),
            fps,
            config: { damping: 16, stiffness: 90 },
          });

          const targetWidth = (skill.value / maxSkillValue) * maxBarWidth;
          const currentWidth = barSpring * targetWidth;
          
          // Animate the number counter
          const displayValue = Math.round(barSpring * skill.value);
          
          // Fade in labels slightly before the bar grows
          const labelOpacity = interpolate(
            frame - delay + 5,
            [0, 15],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={skill.name}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                width: "100%",
                height: `${80 / sortedSkills.length}%`, // Responsive row height
                transition: "none",
              }}
            >
              {/* Skill Label */}
              <div
                style={{
                  width: labelWidth,
                  textAlign: "right",
                  paddingRight: "2%",
                  opacity: labelOpacity,
                  transition: "none",
                }}
              >
                <span
                  style={{
                    fontSize: width * 0.02,
                    fontWeight: 600,
                    color: labelColor,
                    transition: "none",
                  }}
                >
                  {skill.name}
                </span>
              </div>

              {/* Bar */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  width: currentWidth,
                  height: "80%",
                  backgroundColor: primaryColor,
                  borderRadius: "0px 8px 8px 0px", // Rounded on the right side
                  overflow: "hidden", // Hide text if bar is too short initially
                  boxShadow: `0 4px 14px 0 ${primaryColor}40`,
                  transition: "none",
                }}
              >
                {/* Value Label (Inside the bar) */}
                <span
                  style={{
                    marginLeft: "15px", // Padding from the left edge of the bar
                    fontSize: width * 0.018,
                    fontWeight: 700,
                    color: valueColor,
                    whiteSpace: "nowrap",
                    opacity: barSpring > 0.1 ? 1 : 0, // Only show text once bar is somewhat visible
                    transition: "none",
                  }}
                >
                  {skill.customLabel ? skill.customLabel : `$${displayValue}k`}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default HighestPaidSkills;